<script module lang="ts">
/**
 * The application frame (`design/archetypes/app-shell.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import {
  PageTransition,
  Render,
  agentMember,
  currentRailDestination,
  goToRailDestination,
  joinSlot,
  railDestinations,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Button from '../controls/Button.svelte'
import type { AppShellNavGroupProps } from './AppShellNavGroup.svelte'
import type { AppShellNavItemProps } from './AppShellNavItem.svelte'
import type { AppShellUserCardProps } from './AppShellUserCard.svelte'

export type NavItemProps = AppShellNavItemProps

export type NavGroupProps = AppShellNavGroupProps

export type UserCardProps = AppShellUserCardProps

export interface AppShellTopbar {
  leading?: Snippet
  trailing?: Snippet
}

export interface AppShellProps {
  /**
   * One `Banner`: the notice that holds on every page until its cause ends. It takes a row of
   * its own across the frame, above the rail and the topbar, so the rail and the content region
   * shorten by its height and nothing scrolls under it.
   */
  banner?: Snippet
  brand?: Snippet
  children: Snippet
  collapsed?: boolean
  /**
   * A bounded, responsive reading surface for pages composed directly from controls.
   */
  contentLayout?: 'full' | 'page'
  defaultCollapsed?: boolean
  /**
   * A floating layer pinned to the bottom of the content region, for a product's always-present
   * control (a prompt, a player, a selection bar). It shares the content area's grid cell
   * instead of taking its own row. So it floats over the page instead of shortening it, and it
   * re-centres on the content when the rail collapses, because the cell moves. The layer ignores
   * the pointer and its children re-enable it, so the space around the floating control still
   * belongs to the page underneath. A dock overlays content, so a page with a dock leaves room
   * at its bottom.
   */
  dock?: Snippet
  /**
   * Application-localized navigation names.
   */
  messages?: {
    primaryNavigation: string
    expandSidebar: string
    collapseSidebar: string
    closeNavigation: string
    openNavigation: string
    skipToContent?: string
  }
  /**
   * Where the navigation is drawn at frame widths. `'rail'` is the column at the frame's start.
   * `'top'` lays the same navigation along the frame's top row, before the topbar's slots, and
   * the rail's width collapse does not apply. Below the drawer breakpoint both are the same
   * drawer.
   */
  navigation?: 'top' | 'rail'
  onCollapsedChange?: (collapsed: boolean) => void
  pending?: boolean
  /**
   * Nav content, from the vocabulary.
   */
  sidebar: Snippet
  sidebarFooter?: Snippet
  topbar?: AppShellTopbar
  /**
   * Presentation identity for page arrivals; does not key or remount children. A new key also
   * closes the small-viewport drawer.
   */
  transitionKey?: string
}
</script>

<script lang="ts">
let {
  banner,
  brand,
  children,
  collapsed,
  contentLayout = 'full',
  defaultCollapsed,
  dock,
  messages,
  navigation = 'rail',
  onCollapsedChange,
  pending = false,
  sidebar,
  sidebarFooter,
  topbar,
  transitionKey,
}: AppShellProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get banner() {
    return banner
  },
  get brand() {
    return brand
  },
  get default() {
    return children
  },
  get dock() {
    return dock
  },
  get sidebar() {
    return sidebar
  },
  get sidebarFooter() {
    return sidebarFooter
  },
}
// svelte-ignore state_referenced_locally
let uncontrolled = $state(defaultCollapsed ?? false)
let drawer = $state(false)
let drawerToggle = $state<HTMLElement | null>(null)
let rail = $state<HTMLElement | null>(null)
let railToggle = $state<HTMLElement | null>(null)
const held = $derived(collapsed ?? uncontrolled)
const isCollapsed = $derived(navigation === 'rail' && held)
const say = $derived(
  messages ?? {
    primaryNavigation: 'Primary',
    expandSidebar: 'Expand sidebar',
    collapseSidebar: 'Collapse sidebar',
    closeNavigation: 'Close navigation',
    openNavigation: 'Open navigation',
  },
)
const toggle = $derived((): void => {
  const next = !held
  uncontrolled = next
  onCollapsedChange?.(next)
})
setContext('polymorph:AppShell', {
  get collapsed() {
    return isCollapsed
  },
})
const effect1 = () => {
  drawer ? rail?.focus() : drawerToggle?.querySelector<HTMLElement>('button')?.focus()
}
watchEffect(effect1, { watch: () => drawer, mount: false })
const effect2 = () => {
  drawer = false
}
watchEffect(effect2, { watch: () => transitionKey, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'AppShell',
    element: () => rail,
    state: () => ({
      collapsed: isCollapsed,
      open: drawer,
      destinations: railDestinations(rail, { item: styles.navItem, label: styles.navLabel }),
      current: currentRailDestination(rail, { item: styles.navItem, label: styles.navLabel }),
    }),
    actions: {
      collapse: () =>
        (() => {
          if (!railToggle || window.getComputedStyle(railToggle).display === 'none')
            throw new Error(
              'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
            )
          if (!held) toggle()
        })(),
      expand: () =>
        (() => {
          if (!railToggle || window.getComputedStyle(railToggle).display === 'none')
            throw new Error(
              'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
            )
          if (held) toggle()
        })(),
      open: () =>
        (() => {
          if (!drawerToggle || window.getComputedStyle(drawerToggle).display === 'none')
            throw new Error(
              'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
            )
          drawer = true
        })(),
      close: () =>
        (() => {
          if (!drawerToggle || window.getComputedStyle(drawerToggle).display === 'none')
            throw new Error(
              'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
            )
          drawer = false
        })(),
      go: {
        argument: 'id',
        run: (value) =>
          goToRailDestination(rail, { item: styles.navItem, label: styles.navLabel }, value),
      },
    },
    withholds: () => [railToggle, drawerToggle],
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.shell}
    data-collapsed={(isCollapsed) ? '' : undefined}
    data-navigation={(navigation === 'top') ? 'top' : undefined}
    data-drawer={(drawer) ? '' : undefined}
    data-member="app-shell"
    ><a class={styles.skip} href="#content">{say.skipToContent ?? 'Skip to content'}</a
    >{#if slots.banner}<div class={styles.banner}>{@render banner?.()}</div>{/if
    }<nav bind:this={rail} class={styles.sidebar} aria-label={say.primaryNavigation} tabindex="-1"
      ><div class={styles.railHead}
        >{#if slots.brand}<div class={styles.brand}>{@render brand?.()}</div>{/if
        }<div bind:this={railToggle} class={styles.toggle}
          ><Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon={isCollapsed ? 'next' : 'previous'}
            label={isCollapsed ? say.expandSidebar : say.collapseSidebar}
            onClick={() => { toggle() }}
        /></div
      ></div
      ><div class={styles.nav}>{@render sidebar?.()}</div
      >{#if slots.sidebarFooter
        }<div class={styles.sidebarFooter}>{@render sidebarFooter?.()}</div
      >{/if
    }</nav
    ><header class={styles.topbar}
      ><div class={styles.topbarSlot}
        ><span bind:this={drawerToggle} class={styles.drawerToggle}
          ><Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="menu"
            label={drawer ? say.closeNavigation : say.openNavigation}
            onClick={() => { drawer = !drawer }}
        /></span
        >{#if topbar?.leading !== undefined}<Render node={topbar?.leading} />{/if
      }</div
      ><div class={styles.topbarSlot}
        >{#if topbar?.trailing !== undefined}<Render node={topbar?.trailing} />{/if
      }</div
    ></header
    >{#if drawer
      }<button
        class={styles.scrim}
        type="button"
        aria-label={say.closeNavigation}
        onclick={() => { drawer = false }}
      ></button
    >{/if
    }<PageTransition
      class={[styles.content, transitionKey !== undefined ? transitions.page : undefined]}
      as="main"
      id="content"
      {transitionKey}
      {pending}
      ribbon={transitions.indicator}
      >{#if contentLayout === 'page'
        }<div class={styles.page}>{@render children?.()}</div
      >{:else
        }{@render children?.()
      }{/if
    }</PageTransition
    >{#if slots.dock}<div class={styles.dock}>{@render dock?.()}</div>{/if
  }</div
>{/if
}{@render joined.end?.()}
